insert into public.products (name, slug, short_description, description, category_id, images, specifications, customization_options, moq, is_featured, is_active, is_demo)
select 'Premium Executive Gift Box', 'premium-executive-gift-box', 'A rigid, magnet-closure presentation box configured with a curated executive set.', 'A rigid presentation box with a magnetic closure and a custom-cut insert, designed to hold a curated selection of executive items. Ideal for senior client gifting and board-level appreciation. Contents can be configured around your brief.', c.id, '["/images/products/executive-gift-box.jpg"]'::jsonb, '[{"label":"Format","value":"Rigid box, magnetic closure"},{"label":"Insert","value":"Custom-cut foam or card"},{"label":"Size","value":"Configurable (sample: 30 × 22 × 8 cm)"},{"label":"Finish","value":"Soft-touch lamination"}]'::jsonb, '["Hot-foil lid logo","Printed ribbon","Custom insert layout","Personalised card"]'::jsonb, 50, true, true, true
from public.categories c where c.slug = 'gift-sets-hampers'
on conflict (slug) do nothing;
